    if (st.empty()) {
        result = n;
    } else {
        int right = n, left = 0;
        while (!st.empty()) {
            left = st.top();
            st.pop();
            result = std::max(result, right - left - 1);
            right = left;
        }
        result = std::max(result, right);
    }

    return result;
}

