public class Vector2D implements Iterator<Integer> {
    private Iterator<List<Integer>> i;
    private Iterator<Integer> j;

    public Vector2D(List<List<Integer>> vec) {
        i = vec.iterator();
        if (i.hasNext()) {
            j = i.next().iterator();
        }
    }

    @Override
    public Integer next() {
        if (!hasNext()) {
            return null;
        }
        return j.next();
    }

    @Override
    public boolean hasNext() {
        if (j == null) {
            return false;
        }

        while (!j.hasNext() && i.hasNext()) {
            j = i.next().iterator();
        }

        return j.hasNext();
    }
}

