        this.vec = vec;
        this.row = 0;
        this.col = 0;
    }

    next() {
        const val = this.vec[this.row][this.col];
        this.col++;
        return val;
    }

    hasNext() {
        while (this.row < this.vec.length) {
            if (this.col < this.vec[this.row].length) {
                return true;
            }
            this.row++;
            this.col = 0;
        }
        return false;
    }
}

