            char c1 = word1[j], c2 = word2[j];
            if (c1 != c2) {
                if (!graph[c1].count(c2)) {
                    graph[c1].insert(c2);
                    inDegree[c2]++;
                }
                found = true;
                break;
            }
        }

        if (!found && word1.size() > word2.size())
            return "";
    }

    std::queue<char> q;
    for (auto &[c, deg] : inDegree)
        if (deg == 0)
            q.push(c);

    std::string result;
    while (!q.empty()) {
        char c = q.front();
        q.pop();
        result += c;

        for (char neigh : graph[c]) {
            inDegree[neigh]--;
            if (inDegree[neigh] == 0)
                q.push(neigh);
        }
    }

    if (result.size() < inDegree.size())
        return "";

    return result;
