    for (int i = 0; i < n; ++i) {
        if (degrees[i] == 1) q.push(i);
    }

    while (n > 2) {
        int leaves_size = q.size();
        n -= leaves_size;
        for (int i = 0; i < leaves_size; i++) {
            int leaf = q.front(); q.pop();
            for (int neighbor : adjList[leaf]) {
                if (--degrees[neighbor] == 1) q.push(neighbor);
            }
        }
    }

    vector<int> result;
    while (!q.empty()) {
        result.push_back(q.front());
        q.pop();
    }

    return result;
}

