import java.util.ArrayList;
import java.util.List;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

public List<List<Integer>> findLeaves(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    findLeaves(root, result, 0);
    return result;
}

private int findLeaves(TreeNode node, List<List<Integer>> result, int level) {
    if (node == null) return -1;
    int leftLevel = findLeaves(node.left, result, level + 1);
    int rightLevel = findLeaves(node.right, result, level + 1);
    level = Math.max(leftLevel, rightLevel) + 1;
    if (result.size() <= level) result.add(new ArrayList<>());
    result.get(level).add(node.val);
    return level;
}

