#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

void findLeaves(TreeNode* node, std::vector<std::vector<int>>& result, int& level) {
    if (!node) return;
    if (!node->left && !node->right) {
        if (result.size() <= level) {
            result.push_back(std::vector<int>());
        }
        result[level].push_back(node->val);
        node = nullptr;
        return;
    }
    level++;
    findLeaves(node->left, result, level);
    findLeaves(node->right, result, level);
    level--;
}

std::vector<std::vector<int>> findLeaves(TreeNode* root) {
    std::vector<std::vector<int>> result;
    int level = 0;
    while (root) {
        findLeaves(root, result, level);
        if (!root->left && !root->right) root = nullptr;
    }
    return result;
}

