public int getMoneyAmount(int n) {
    int[][] dp = new int[n + 1][n + 1];
    for (int i = n - 1; i >= 1; i--) {
        for (int j = i + 1; j <= n; j++) {
            int min_cost = Integer.MAX_VALUE;
            for (int k = i; k < j; k++) {
                int cost = k + Math.max(dp[i][k - 1], dp[k + 1][j]);
                min_cost = Math.min(min_cost, cost);
            }
            dp[i][j] = min_cost;
        }
    }
    return dp[1][n];
}

