    for (int i = 0; i < equations.size(); i++) {
        graph[equations[i][0]].push_back({equations[i][1], values[i]});
        graph[equations[i][1]].push_back({equations[i][0], 1 / values[i]});
    }

    vector<double> ans;
    for (const auto& q : queries) {
        ans.push_back(dfs(q[0], q[1], graph));
    }
    return ans;
}

