        char c = expression[i];
        if (!stk.empty() && stk.top() == '?') {
            stk.pop(); // Pop '?'
            char first = stk.top();
            stk.pop();
            stk.pop(); // Pop ':'
            char second = stk.top();
            stk.pop();
            stk.push(c == 'T' ? first : second);
        } else {
            stk.push(c);
        }
    }
    return std::string(1, stk.top());
}

