public boolean isConvex(int[][] points) {
    int n = points.length;
    int pre = 0, cur = 0;

    for (int i = 0; i < n; ++i) {
        int x1 = points[(i + 1) % n][0] - points[i][0];
        int y1 = points[(i + 1) % n][1] - points[i][1];
        int x2 = points[(i + 2) % n][0] - points[(i + 1) % n][0];
        int y2 = points[(i + 2) % n][1] - points[(i + 1) % n][1];
        cur = x1 * y2 - x2 * y1;

        if (cur == 0)
            continue;
        if (cur * pre < 0)
            return false;
        pre = cur;
    }

    return true;
}

