        let j = mid + 1;
        for (let i = l; i <= mid; i++) {
            while (j <= r && nums[i] > 2 * nums[j]) {
                j++;
            }
            count += j - (mid + 1);
        }

        const merged = nums.slice(l, r + 1).sort((a, b) => a - b);
        nums.splice(l, merged.length, ...merged);

        return count;
    }

    return mergeSort(0, nums.length - 1);
}

