    boolean[] marked = new boolean[n];
    for (String word : words) {
        int pos = s.indexOf(word, 0);
        while (pos != -1) {
            Arrays.fill(marked, pos, pos + word.length(), true);
            pos = s.indexOf(word, pos + 1);
        }
    }
