#include <algorithm>
#include <queue>
#include <vector>

int scheduleCourse(std::vector<std::vector<int>>& courses) {
    std::sort(courses.begin(), courses.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[1] < b[1];
    });

    std::priority_queue<int> pq;
    int time = 0;

    for (const auto& course : courses) {
        time += course[0];
        pq.push(course[0]);

        if (time > course[1]) {
            time -= pq.top();
            pq.pop();
        }
    }

    return pq.size();
}

