        row--; column -= 'A';
        string pos = string(1, column + 'A') + to_string(row + 1);
        if (formulas.count(pos)) {
            int sum = 0;
            for (string &r : formulas[pos].second) {
                auto x = r.find(':');
                if (x == string::npos) {
                    int rRow = stoi(r.substr(1)) - 1;
                    int rCol = r[0] - 'A';
                    sum += get(rRow + 1, rCol + 'A');
                } else {
                    int r1Row = stoi(r.substr(1, x - 1)) - 1;
                    int r1Col = r[0] - 'A';
                    int r2Row = stoi(r.substr(x + 2)) - 1;
                    int r2Col = r[x + 1] - 'A';
                    for (int i = r1Row; i <= r2Row; ++i)
                        for (int j = r1Col; j <= r2Col; ++j)
