    depth = 0
    q = deque([root])
    while q:
        depth += 1
        for _ in range(len(q)):
            node = q.popleft()
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)

    res = [["" for _ in range((1 << depth) - 1)] for _ in range(depth)]

    # Fill in matrix
    q.append(root)
    level = 0
    step = (1 << (depth - 1))
    while q:
        cur_pos = step - 1
        for _ in range(len(q)):
            node = q.popleft()
            res[level][cur_pos] = str(node.val)
            cur_pos += (step << 1)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        step >>= 1
        level += 1

    return res

