    const result = [];
    let previous = [-1, null];

    while (pq.length) {
        const current = pq.shift();
        result.push(current[0]);

        if (previous[0] > 0) {
            pq.push(previous);
        }

        current[1]--;
        previous = current;
        pq.sort((a, b) => b[1] - a[1]);
    }

    const resultStr = result.join('');
    return resultStr.length === s.length ? resultStr : "";
}

