private void backtrack(char[] s, int index, List<String> result) {
    if (index == s.length) {
        result.add(new String(s));
        return;
    }
    backtrack(s, index + 1, result);
    if (Character.isLetter(s[index])) {
        s[index] ^= (1 << 5);
        backtrack(s, index + 1, result);
        s[index] ^= (1 << 5);
    }
}

