    }

    int m = grid.length, n = grid[0].length;
    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    int dfs(int x, int y) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] <= 0) {
            return 0;
        }
        grid[x][y] = -1;
        int sum = 1;
        for (int[] d : directions) {
            sum += dfs(x + d[0], y + d[1]);
        }
        return sum;
    }

    for (int i = 0; i < n; ++i) {
        if (grid[0][i] == 1) {
            dfs(0, i);
        }
