            char cPattern = pattern[i];

            if (!w2p.count(cWord)) w2p[cWord] = cPattern;
            if (!p2w.count(cPattern)) p2w[cPattern] = cWord;

            if (w2p[cWord] != cPattern || p2w[cPattern] != cWord) {
                matches = false;
                break;
            }
        }
        if (matches) result.push_back(word);
    }
    return result;
