class FreqStack {
    std::unordered_map<int, int> freq;
    std::map<int, std::stack<int>> group;

public:
    FreqStack() {}

    void push(int x) {
        int f = ++freq[x];
        group[f].push(x);
    }

    int pop() {
        auto& st = group.rbegin()->second;
        int x = st.top();
        st.pop();
        if (st.empty()) {
            group.erase(group.rbegin()->first);
        }
        --freq[x];
        return x;
    }
