class StockSpanner {
    private final Stack<Integer> indexStack;
    private final List<Integer> prices;

    public StockSpanner() {
        indexStack = new Stack<>();
        prices = new ArrayList<>();
    }

    public int next(int price) {
        while (!indexStack.isEmpty() && prices.get(indexStack.peek()) <= price) {
            indexStack.pop();
        }
        int span = indexStack.isEmpty() ? prices.size() + 1 : prices.size() - indexStack.peek();
        indexStack.push(prices.size());
        prices.add(price);
        return span;
    }
}

