public int maxTurbulenceSize(int[] arr) {
    int n = arr.length;
    int result = 1;
    int i = 0;

    while (i < n - 1) {
        if (arr[i] == arr[i + 1]) {
            i++;
            continue;
        }

        int j = i + 1;
        while (j < n - 1 && ((arr[j] > arr[j + 1]) != (arr[j - 1] > arr[j])))
            j++;

        result = Math.max(result, j - i + 1);
        i = j;
    }

    return result;
}

