function addToArrayForm(num, k) {
    for (let i = num.length - 1; i >= 0; --i) {
        let sum = num[i] + k % 10;
        k = Math.floor(k / 10);
        if (sum >= 10) {
            sum -= 10;
            k++;
        }
        num[i] = sum;
        if (k === 0)
            break;
    }
    while (k !== 0) {
        num.unshift(k % 10);
        k = Math.floor(k / 10);
    }
    return num;
}

