            if (tops[i] != target && bottoms[i] != target) {
                top_rot = bot_rot = INT_MAX;
                break;
            }
            top_rot += tops[i] != target;
            bot_rot += bottoms[i] != target;
        }
        res = std::min({res, top_rot, bot_rot});
    }

    return res == INT_MAX ? -1 : res;
}

