        return a.first > b.first;
    });

    std::unordered_map<int, int> labelCount;
    int ans = 0;

    for (const auto& item : items) {
        if (labelCount[item.second] < useLimit) {
            ans += item.first;
            labelCount[item.second]++;
            if (--numWanted == 0) break;
        }
    }
    return ans;
}

