void helper(istringstream &iss, TreeNode* &node, int depth) {
    int d = 0;
    while (iss.peek() == '-') {
        iss.get();
        d++;
    }
    if (d != depth) {
        iss.putback('-');
        return;
    }
    int val;
    iss >> val;
    node = new TreeNode(val);
    helper(iss, node->left, depth + 1);
    helper(iss, node->right, depth + 1);
}

TreeNode* recoverFromPreorder(string S) {
    istringstream iss(S);
    TreeNode* root = nullptr;
    helper(iss, root, 0);
    return root;
}

