public int numKLenSubstrNoRepeats(String s, int k) {
    int n = s.length();
    if (k > n) return 0;

    int result = 0;
    HashSet<Character> window = new HashSet<>();

    for (int i = 0, j = 0; j < n; ++j) {
        while (window.contains(s.charAt(j))) {
            window.remove(s.charAt(i++));
        }
        window.add(s.charAt(j));
        if (j - i + 1 == k) {
            ++result;
            window.remove(s.charAt(i++));
        }
    }
    return result;
}

