    TreeNode *left;
    TreeNode *right;
};

pair<TreeNode*, int> findLCAUtil(TreeNode* root) {
    if (root == nullptr) {
        return {nullptr, 0};
    }

    pair<TreeNode*, int> leftLCA = findLCAUtil(root->left);
    pair<TreeNode*, int> rightLCA = findLCAUtil(root->right);

    if (leftLCA.second > rightLCA.second) {
        return {leftLCA.first, leftLCA.second + 1};
    } else if (leftLCA.second < rightLCA.second) {
        return {rightLCA.first, rightLCA.second + 1};
    } else {
        return {root, leftLCA.second + 1};
    }
}

