        graph[prev].push(next);
        in_degree[next]++;
    }

    const q = [];
    for (let i = 1; i <= n; i++) {
        if (in_degree[i] === 0) {
            q.push(i);
        }
    }

    let semesters = 0;
    while (q.length) {
        const size = q.length;
        semesters++;
        for (let i = 0; i < size; i++) {
            const course = q.shift();
            n--;

            for (let next of graph[course]) {
                in_degree[next]--;
                if (in_degree[next] === 0) {
                    q.push(next);
                }
            }
        }
    }

    return n === 0 ? semesters : -1;
}

