public int minHeightShelves(int[][] books, int shelfWidth) {
    int n = books.length;
    int[] dp = new int[n + 1];
    Arrays.fill(dp, 1000000);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int width = 0, height = 0;
        for (int j = i; j >= 1; j--) {
            width += books[j - 1][0];
            height = Math.max(height, books[j - 1][1]);

            if (width <= shelfWidth)
                dp[i] = Math.min(dp[i], dp[j - 1] + height);
        }
    }

    return dp[n];
}

