    const current = expression[pos[0]++];
    if (current === 't') return true;
    if (current === 'f') return false;
    if (current === '!') {
        pos[0]++;
        return !parseBoolExpr(expression, pos);
    }
    if (current === '&') {
        pos[0]++;
        let result = true;
        while (expression[pos[0]] !== ')') {
            result &= parseBoolExpr(expression, pos);
            if (expression[pos[0]] === ',') pos[0]++;
        }
    } else if (current === '|') {
        pos[0]++;
        let result = false;
        while (expression[pos[0]] !== ')') {
            result |= parseBoolExpr(expression, pos);
            if (expression[pos[0]] === ',') pos[0]++;
        }
    }
    pos[0]++;
    return result;
}

