    const n = s.length;
    const p = Array.from({length: n}, (_, i) => i);

    const find = x => {
        if (p[x] !== x) p[x] = find(p[x]);
        return p[x];
    };

    for (const [x, y] of pairs) {
        p[find(y)] = find(x);
    }

    const groups = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) {
        const root = find(i);
        groups[root].push(s[i]);
