    for (const group of groups) {
        group.sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0));
    }

    let result = '';
    for (let i = 0; i < n; i++) {
        const root = find(i);
        result += groups[root].pop();
    }

    return result;
};

