import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
    List<TreeNode> forest = new ArrayList<>();
    Set<Integer> toDelete = new HashSet<>();
    for (int val : to_delete) {
        toDelete.add(val);
    }
    helper(root, true, toDelete, forest);
    return forest;
}

private TreeNode helper(TreeNode node, boolean isRoot, Set<Integer> toDelete, List<TreeNode> forest) {
    if (node == null) return null;
    boolean deleted = toDelete.contains(node.val);
    if (isRoot && !deleted) forest.add(node);
    node.left = helper(node.left, deleted, toDelete, forest);
    node.right = helper(node.right, deleted, toDelete, forest);
    return deleted ? null : node;
}

