public int maxSumSubsequence(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    int result = 0;

    for (int i = 0; i < n; ++i) {
        dp[i] = nums[i];
        for (int j = Math.max(0, i - k); j < i; ++j) {
            dp[i] = Math.max(dp[i], dp[j] + nums[i]);
        }
        result = Math.max(result, dp[i]);
    }

