    int[][] moves = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    q.offer(new int[]{0, 0, 0, k});

    int steps = 0;
    while (!q.isEmpty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            int[] tmp = q.poll();
            int x = tmp[0];
            int y = tmp[1];
            if (x == m - 1 && y == n - 1) return steps;

            for (int[] move : moves) {
                int newX = x + move[0];
