    for (int i = 2; i <= cnt; i++) {
        res = (res * i) % MOD;
    }

    return memo[idx] = res;
}

int numOfWays(vector<int>& prevRoom) {
    int n = prevRoom.size();
    vector<vector<int>> children(n);
    for (int i = 1; i < n; i++) {
        children[prevRoom[i]].push_back(i);
    }

    vector<int> memo(n, -1);
    return addRooms(0, children, memo);
}

