        for i in range(6):
            dp[i][j] = sum_dp[j - 1]
            if j - rollMax[i] - 1 >= 0:
                dp[i][j] = (dp[i][j] - sum_dp[j - rollMax[i] - 1] + MOD) % MOD
                if j - rollMax[i] - 1 >= 1:
