    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    TreeNode* balanceBST(TreeNode* root) {
        vector<TreeNode*> sortedNodes;
        inorderTraversal(root, sortedNodes);
        return sortedArrayToBST(sortedNodes, 0, sortedNodes.size() - 1);
    }

    void inorderTraversal(TreeNode* node, vector<TreeNode*>& sortedNodes) {
        if (node == nullptr) return;
        inorderTraversal(node->left, sortedNodes);
        sortedNodes.push_back(node);
        inorderTraversal(node->right, sortedNodes);
    }

    TreeNode* sortedArrayToBST(vector<TreeNode*>& sortedNodes, int start, int end) {
        if (start > end) return nullptr;
        int mid = start + (end - start) / 2;
        TreeNode* newNode = sortedNodes[mid];
        newNode->left = sortedArrayToBST(sortedNodes, start, mid - 1);
        newNode->right = sortedArrayToBST(sortedNodes, mid + 1, end);
        return newNode;
    }
};

