    const freqMap = new Map([...s]
        .sort()
        .reduce((acc, c) => {
            acc.set(c, (acc.get(c) || 0) + 1);
            return acc;
        }, new Map()));
    let result = '';

    while (freqMap.size) {
        for (const [key, val] of freqMap) {
            result += key;
            if (val - 1 === 0) {
                freqMap.delete(key);
            } else {
                freqMap.set(key, val - 1);
            }
        }

        for (const [key, val] of [...freqMap].reverse()) {
            result += key;
            if (val - 1 === 0) {
                freqMap.delete(key);
            } else {
                freqMap.set(key, val - 1);
            }
        }
    }

    return result;
}

