int minNumberOfSemesters(int n, vector<vector<int>>& relations, int k) {
    vector<int> indegree(n + 1, 0);
    vector<vector<int>> graph(n + 1);

    for (const auto& relation : relations) {
        graph[relation[0]].push_back(relation[1]);
        indegree[relation[1]]++;
