    int semesters = 0;
    while (n > 0) {
        queue<int> zero_indegree;
        for (int i = 1; i < indegree.size(); ++i) {
            if (indegree[i] == 0) {
                zero_indegree.push(i);
                indegree[i] = -1;
            }
        }

        int courses = 0;
        while (!zero_indegree.empty() && courses < k) {
            int curr_course = zero_indegree.front();
            zero_indegree.pop();
            n--;

            for (int next_course : graph[curr_course]) {
                indegree[next_course]--;
            }
            courses++;
        }
        semesters++;
    }
    return semesters;
}

