            parent[x] = find(parent[x]);
        return parent[x];
    }

    bool unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
            components--;
            return true;
        }
        return false;
    }
};

int maxNumEdgesToRemove(int n, vector<vector<int>> &edges) {
    UnionFind ufA(n + 1), ufB(n + 1);
    int common_edges = 0;

    for (auto &edge : edges) {
        if (edge[0] == 3) {
            if (ufA.unite(edge[1], edge[2])) {
                ufB.unite(edge[1], edge[2]);
                common_edges++;
            }
        }
