import java.util.HashMap;

public int minSubarray(int[] nums, int p) {
    int n = nums.length, res = n, need = 0, cur = 0;
    for (int num : nums)
        need = (need + num) % p;
    if (need == 0) return 0;
    HashMap<Integer, Integer> last_seen = new HashMap<>();
    last_seen.put(0, -1);
    for (int i = 0; i < n; i++) {
        cur = (cur + nums[i]) % p;
        last_seen.put(cur, i);
        res = Math.min(res, i - last_seen.getOrDefault((cur - need + p) % p, -n));
    }
    return res < n ? res : -1;
}

