                return True

            if dfs(new_x, new_y, start_x, start_y, depth + 1):
                return True

        grid[x][y] = grid[start_x][start_y]

        return False

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if dfs(i, j, i, j, 0):
                return True

    return False

