private boolean dfs(int[] res, int i, boolean[] used) {
    if (i == res.length) {
        return true;
    }
    if (res[i] != 0) {
        return dfs(res, i + 1, used);
    }
    for (int num = used.length - 1; num > 0; num--) {
        if (!used[num] && (num == 1 || (i + num < res.length && res[i + num] == 0))) {
            res[i] = num;
            if (num > 1) {
                res[i + num] = num;
            }
            used[num] = true;
            if (dfs(res, i + 1, used)) {
                return true;
            }
            res[i] = 0;
            if (num > 1) {
                res[i + num] = 0;
            }
            used[num] = false;
        }
    }
    return false;
}

