    for (int i = 0; i < n; ++i) {
        dp[i] = players[i].second;
        for (int j = 0; j < i; ++j) {
            if (players[i].second >= players[j].second) {
                dp[i] = max(dp[i], dp[j] + players[i].second);
            }
        }
        best_score = max(best_score, dp[i]);
    }

    return best_score;
}

