    string result = "";
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; ++j) {
            bool isNice = true;
            for (char ch = 'A'; ch <= 'Z'; ++ch) {
                bool upper = false, lower = false;
                for (int k = i; k <= j; ++k) {
                    if (s[k] == ch) upper = true;
                    if (s[k] == (ch + 32)) lower = true;
                }
                if ((upper && !lower) || (!upper && lower)) {
                    isNice = false;
                    break;
                }
            }
            if (isNice && j - i + 1 > result.length()) {
                result = s.substr(i, j - i + 1);
            }
        }
    }
    return result;
}

