            closest = Math.min(closest, Math.abs(cost - target));
            return;
        }

        dfs(index + 1, cost);
        dfs(index + 1, cost + toppingCosts[index]);
        dfs(index + 1, cost + 2 * toppingCosts[index]);
    }

    for (const base of baseCosts) {
        dfs(0, base);
    }

    return target - (closest > target ? -closest : closest);
}

