int minimumIncompatibility(vector<int>& nums, int k) {
    int n = nums.size();
    if (n % k != 0) return -1;

    sort(nums.begin(), nums.end());
    multiset<int> st;
    for (int i = 0; i < k; ++i) {
        st.insert(nums[i * (n / k)] - nums[(i + 1) * (n / k) - 1]);
    }

    return accumulate(st.begin(), st.end(), 0);
}

