public int stoneGame(int[] stones) {
    int n = stones.length;
    int[][] dp = new int[n][n];

    for (int i = n - 1; i >= 0; i--) {
        for (int j = i + 1; j < n; j++) {
            dp[i][j] = Math.max(stones[j] - dp[i][j - 1], stones[i] - dp[i + 1][j]);
        }
    }

    return dp[0][n - 1];
}

