int stoneGame(vector<int>& stones) {
    int n = stones.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int i = n - 1; i >= 0; --i) {
        for (int j = i + 1; j < n; ++j) {
            dp[i][j] = max(stones[j] - dp[i][j - 1], stones[i] - dp[i + 1][j]);
        }
    }

    return dp[0][n - 1];
}

