    def findShortestPath(self, master: 'GridMaster') -> int:
        def dfs(master, x, y):
            nonlocal target
            if master.isTarget():
                target = (x, y)
            for i in range(4):
                nx, ny = x + dirs[i], y + dirs[i + 1]
                if (nx, ny) in grid:
                    continue
                if master.canMove(DIR_CHAR[i]):
                    cost = master.move(DIR_CHAR[i])
                    grid[(nx, ny)] = cost
                    dfs(master, nx, ny)
                    master.move(OPPOSITE_DIR_CHAR[i])

        def bfs():
            q = deque([(0, 0)])
            grid[(0, 0)] = 0
            while q:
                x, y = q.popleft()
                for i in range(4):
                    nx, ny = x + dirs[i], y + dirs[i + 1]
                    cost = grid[(x, y)] + grid.get((nx, ny), 0)
                    if (nx, ny) in grid and grid[(nx, ny)] > cost:
                        grid[(nx, ny)] = cost
                        if (nx, ny) != target:
                            q.append((nx, ny))
            return grid.get(target, -1)

        dirs = [-1, 0, 1, 0, -1]
        DIR_CHAR = "URDL"
        OPPOSITE_DIR_CHAR = "DLUR"
        grid = {}
        target = None

        dfs(master, 0, 0)
        if target is None:
            return -1

        return bfs()

