private:
    map<pair<int, int>, int> grid;
    pair<int, int> target = {INT_MAX, INT_MAX};
    int dirs[5] = {-1, 0, 1, 0, -1};

    void dfs(GridMaster &master, int x, int y) {
        if (master.isTarget()) {
            target = {x, y};
        }
        for (int i = 0; i < 4; i++) {
            int nx = x + dirs[i], ny = y + dirs[i + 1];
            if(grid.count({nx, ny})) continue;
            if (master.canMove(dir_char[i])) {
                int cost = master.move(dir_char[i]);
                grid[{nx, ny}] = cost;
                dfs(master, nx, ny);
                master.move(opposite_dir_char[i]);
            }
        }
    }

    int bfs() {
        queue<pair<int, int>> q;
        q.push({0, 0});
        grid[{0, 0}] = 0;
        while(!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            for (int i = 0; i < 4; i++) {
                int nx = x + dirs[i], ny = y + dirs[i + 1];
                int cost = grid[{x, y}] + grid[{nx, ny}];
                if(grid.count({nx, ny}) && grid[{nx, ny}] > cost) {
                    grid[{nx, ny}] = cost;
                    if (nx != target.first || ny != target.second) {
                        q.push({nx, ny});
                    }
                }
            }
        }
        return grid[target];
    }

    char dir_char[4] = {'U', 'R', 'D', 'L'};
    char opposite_dir_char[4] = {'D', 'L', 'U', 'R'};
};

