class PriorityQueue {
  constructor(k) {
    this.queue = [];
    this.k = k;
  }

  offer(element) {
    this.queue.push(element);
    this.queue.sort((a, b) => a - b);
  }

  poll() {
    return this.queue.shift();
  }

  size() {
    return this.queue.length;
  }

  peek() {
    return this.queue[0];
  }
}

