    for (int mask = 0; mask < (1 << right.size()); ++mask) {
        int sum = 0;
        for (int i = 0; i < right.size(); ++i) {
            if (mask & (1 << i)) {
                sum += right[i];
            }
        }
        auto it = sums.lower_bound(goal - sum);
        if (it != sums.end()) {
            ans = std::min(ans, std::abs((*it) + sum - goal));
