    priority_queue<pair<long long, int>> pq;
    pq.push({0, n});
    dist[n] = 0;

    while (!pq.empty()) {
        int u = pq.top().second;
        long long d = -pq.top().first;
        pq.pop();

        if (d != dist[u]) continue;

        for (auto& to : graph[u]) {
            int v = to.first, w = to.second;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({-dist[v], v});
            }
        }
