#include <set>
#include <queue>
#include <algorithm>

class MKAverage {
public:
    int m, k;
    long long sum = 0;
    multiset<int> minSet, midSet, maxSet;
    queue<int> q;

    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int num) {
        if (q.size() == m) {
            removeElement();
        }

        minSet.insert(num);
        sum += num;

        if (minSet.size() > k) {
            int temp = *minSet.rbegin();
            minSet.erase(minSet.find(temp));
            midSet.insert(temp);
            sum += temp;
        }

        if (!midSet.empty() && *minSet.rbegin() > *midSet.begin()) {
            int temp1 = *minSet.rbegin();
            int temp2 = *midSet.begin();
            minSet.erase(minSet.find(temp1));
            midSet.erase(midSet.find(temp2));
            minSet.insert(temp2);
            midSet.insert(temp1);
            sum += temp2 - temp1;
        }

        maxSet.insert(*midSet.rbegin());
        sum -= *midSet.rbegin();
        midSet.erase(prev(midSet.end()));

        if (maxSet.size() > k) {
            int temp = *maxSet.begin();
            maxSet.erase(maxSet.find(temp));
            midSet.insert(temp);
            sum += temp;
        }

        q.push(num);
    }

    int calculateMKAverage() {
        if (q.size() < m) {
            return -1;
        }
        return sum / (m - 2 * k);
    }

    void removeElement() {
        int temp = q.front();
        q.pop();

        if (minSet.count(temp)) {
            minSet.erase(minSet.find(temp));
        } else if (midSet.count(temp)) {
            midSet.erase(midSet.find(temp));
            sum -= temp;
        } else {
            maxSet.erase(maxSet.find(temp));
        }
    }
};

