public int maxFrequency(int[] nums, int k) {
    Arrays.sort(nums);
    int max_freq = 1, n = nums.length;
    long sum = 0;
    for (int i = 0, j = 0; j < n; ++j) {
        sum += nums[j];
        while (sum < (long) nums[j] * (j - i + 1) - k) {
            sum -= nums[i++];
        }
        max_freq = Math.max(max_freq, j - i + 1);
    }
    return max_freq;
}

