import java.util.*;

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        TreeSet<Integer> ms = new TreeSet<>();
        for (int sum : sums) {
            ms.add(sum);
        }

        ArrayList<Integer> ans = new ArrayList<>();
        while (ans.size() < n) {
            ms.pollFirst();
            int cur = ms.first();
            TreeSet<Integer> tmp = new TreeSet<>(ms);
            for (int i : ans) {
                tmp.remove(cur - i);
            }
            ans.add(cur);
            ms = tmp;
        }

        return ans.stream().mapToInt(i -> i).toArray();
    }
}

