    MovieRentingSystem(int n, vector<vector<int>>& entries) {
        for (const auto& entry : entries) {
            int shop = entry[0], movie = entry[1], p = entry[2];
            price[shop][movie] = p;
            if (available.size() <= movie) {
                available.resize(movie + 1);
            }
            available[movie].emplace(p, shop);
        }
    }

    vector<int> search(int movie) {
        vector<int> result;
        auto it = available[movie].begin();
        for (int i = 0; i < 5 && it != available[movie].end(); ++i, ++it) {
            result.push_back(it->second);
        }
        return result;
    }

    void rent(int shop, int movie) {
        int p = price[shop][movie];
        rented.emplace(p, shop);
        available[movie].erase({p, shop});
    }

    void drop(int shop, int movie) {
        int p = price[shop][movie];
        rented.erase({p, shop});
        available[movie].emplace(p, shop);
    }

    vector<vector<int>> report() {
        vector<vector<int>> result;
        auto it = rented.begin();
        for (int i = 0; i < 5 && it != rented.end(); ++i, ++it) {
            result.push_back({it->second, price[it->second]});
        }
        return result;
    }
};

