public int colorTheGrid(int m, int n) {
    long mod = 1000000007;
    long[] dp = {6, 6};
    long[] dpf = {3, 3};

    for (int i = 2; i <= Math.max(m, n); ++i) {
        long temp = dp[1];
        dp[1] = (dpf[1] * 2) % mod;
        dp[0] = temp;
        dpf[1] = (dpf[1] + dpf[0]) % mod;
        dpf[0] = (dpf[0] + temp) % mod;
    }

    return (int)((dp[m == 1 ? 0 : 1] * dpf[n == 1 ? 0 : 1]) % mod);
}

