def slanted_transposition_cipher(encodedText, rows):
    if rows == 1:
        return encodedText

    n = len(encodedText)
    cols = (n + rows - 2) // (rows - 1)
    pos = 0
    matrix = [[' ' for col in range(cols)] for row in range(rows)]
    for k in range(cols):
        for i in range(rows):
            if k % 2 == 0 or i != 0:
                matrix[i][k] = encodedText[pos]
                pos += 1

    originalText = ''.join(''.join(row) for row in matrix)

