def numberOfLists(num: str) -> int:
    mod = 10 ** 9 + 7
    n = len(num)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(1, n + 1):
            if num[i] == '0': continue
            for k in range(1, min(n - i + 1, 11)):
                if k > 1 and num[i + k - 1] == '0': break
                dp[i + k][j] = (dp[i + k][j] + dp[i][j - 1]) % mod

    return sum(dp[n]) % mod

