import java.util.*;

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int sum : sums) {
            map.put(sum, map.getOrDefault(sum, 0) + 1);
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            int num = map.firstKey();
            decrement(map, num);
            for (int prevNum : ans) {
                decrement(map, num - prevNum);
            }
            ans[i] = num;
        }
        return ans;
    }

    private void decrement(TreeMap<Integer, Integer> map, int key) {
        int count = map.get(key) - 1;
        if (count == 0) {
            map.remove(key);
        } else {
            map.put(key, count);
        }
    }
}

