from collections import defaultdict, deque

def has_path(n, edges, source, destination):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    q = deque([source])
    visited = [False] * n
    while q:
        current = q.popleft()
        visited[current] = True
        if current == destination:
            return True
        for neighbor in graph[current]:
            if not visited[neighbor]:
                q.append(neighbor)
    return False

