    int n = nextVisit.length;
    long ans = 0, MOD = 1000000007;
    long[] dp = new long[n];

    for (int i = 1; i < n; ++i) {
        dp[i] = (dp[i - 1] + 1 + dp[i - 1] - dp[nextVisit[i - 1]] + MOD) % MOD;
        ans = (ans + dp[i]) % MOD;
    }
    return (int) ans;
}

