public int numberOfBalancedRanges(int[] nums1, int[] nums2) {

    int n = nums1.length;
    int[][][][] dp = new int[n][n][n][3];
    dp[0][0][0][0] = 2;
    int[] sums1 = new int[n + 1], sums2 = new int[n + 1];
    for (int i = 0, s1 = 0, s2 = 0; i < nums1.length; i++) {
        s1 += nums1[i];
        s2 += nums2[i];
        sums1[i + 1] = s1;
        sums2[i + 1] = s2;
    }
    int MOD = 1_000_000_007;

    int ans = 0;
    for (int r = 0; r < nums1.length; ++r) {
        for (int l = r + 1; --l >= 0;) {
            for (int k = l; k <= r; ++k) {
                int leftSum1 = sums1[l];
                int rightSum1 = sums1[n] - sums1[k + 1];
                int leftSum2 = sums2[l];
                int rightSum2 = sums2[n] - sums2[r + 1];

                if (leftSum1 + rightSum2 == leftSum2 && leftSum1 + rightSum1 == rightSum2) {
                    for (int last = 0; last <= 2; ++last) {
                        ans += dp[l][r][k][last];
                        ans %= MOD;
                        int next = last == 2 ? k + 1 : k;
                        dp[next][k != 0 ? k : r + 1][k != 0 ? k - 1 : r + 2][last] +=
                            dp[l][r][k][last];
                        dp[l][r][k][last] =
                            (dp[l][r][k][last] + (!last || last == 2)) % MOD;
                    }
                }
            }
        }
    }
    return ans;
}

