import java.util.Arrays;

public int[] missingRolls(int[] rolls, int mean, int n) {
    int m = rolls.length;
    int sum = mean * (n + m);
    for (int roll: rolls) {
        sum -= roll;
    }

    if (sum < n || sum > 6 * n) {
        return new int[] {};
    }

    int[] ans = new int[n];
    Arrays.fill(ans, 1);
    sum -= n;
    for (int i = 0; i < n; i++) {
        int add = Math.min(5, sum);
        ans[i] += add;
        sum -= add;
    }

    return ans;
}

