def smallest_subsequence(s, k, letter, repetition):
    result = []
    letter_count = s.count(letter)

    pq = []
    for c in s:
        if c <= letter or letter_count > repetition:
            while pq and pq[0] > c:
                if heappop(pq) == letter:
                    letter_count -= 1
            heappush(pq, c)
            if len(pq) > k:
                heappop(pq)
