int second_minimum(int n, const std::vector<std::vector<int>>& edges, int time, int change) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }

    std::vector<int> dist(n + 1, -1);
    std::priority_queue<int, std::vector<int>, std::greater<int>> q;
    dist[1] = 0;
    q.push(0);

    while (!q.empty()) {
        int cur = q.top();
        q.pop();

        int v1 = cur >> 16;
        int t1 = cur & 0xffff;

        if (v1 == n) {
            return t1; // Found the second minimum
        }

        for (int v2 : adj[v1]) {
            int t2 = t1 + time;
            int waiting = (t2 / change) % 2 == 1 ? change - (t2 % change) : 0;

            if (dist[v2] == -1 || dist[v2] > t2 + waiting) {
                if (dist[v2] != -1)
                    q.push(dist[v2] << 16 | v2); // Push the old distance to find the second minimum one
                dist[v2] = t2 + waiting;
                q.push(dist[v2] << 16 | v2);
            }
        }
    }
    return -1;
