public int[] groupStrings(String[] words) {
    Map<String, Integer> groups = new HashMap<>();
    int groupsCount = 0;

    for (String word : words) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        String sKey = new String(chars);

        if (!groups.containsKey(sKey)) {
