        while (!q.empty()) {
            int current = q.front();
            q.pop();

            if (current == end) {
                return current;
            }

            for (int neighbor : tree[current]) {
                if (!visited[neighbor]) {
                    q.push(neighbor);
                    visited[neighbor] = true;
                }
            }
        }
        return -1;
    };

