        for (int j = 0; j < k - 1; j++) {
            if (nums[i + j + 1] < nums[i + j + 2]) {
                rightNonDec = false;
                break;
            }
        }

        if (leftNonInc && rightNonDec) {
            goodIndices.add(i);
        }
    }
    return goodIndices;
}

