        if (nums[i] == nums[j]) {
            i++;
            j--;
        } else if (nums[i] < nums[j]) {
            nums[i + 1] += nums[i];
            i++;
            operations++;
        } else {
            nums[j - 1] += nums[j];
            j--;
            operations++;
        }
    }
    return operations;
}

