int hireWorkers(vector<int>& costs, int k, int candidates) {
    int n = costs.size();
    vector<pair<int, int>> workers;
    for (int i = 0; i < n; ++i) 
        workers.emplace_back(costs[i], i);
    sort(workers.begin(), workers.end());

    int cost = 0;
    for (int i = 0; i < k; ++i) {
        if (min(workers[i].second, n - workers[i].second - 1) < candidates)
            cost += workers[i].first;
    }
    return cost;
}

