def modPow(x, n, mod):
    res = 1
    while n > 0:
        if n % 2 == 1:
            res = (res * x) % mod
        x = (x * x) % mod
        n //= 2
    return res

def goodStrings(low, high, zero, one):
    mod = 1000000007
    good_strs = ((modPow(2, high, mod) - modPow(2, low - 1, mod) + 1) * (zero + 1)) % mod
    return (good_strs * (one + 1)) % mod

