    while ((temp % b) != 0) {
        temp += a;
    }
    return temp;
}

int countLCMSubarrays(std::vector<int>& nums, int k) {
    int count = 0;
    for (int i = 0; i < nums.size(); i++) {
        int curr_lcm = nums[i];
        for (int j = i; j < nums.size(); j++) {
            curr_lcm = lcm(curr_lcm, nums[j]);
            if (curr_lcm == k) {
                count++;
            }
        }
    }
    return count;
}

