    count = 0
    dp = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if i == j:
                dp[i][j] = True
            elif s[i] == s[j]:
                dp[i][j] = i + 1 > j - 1 or dp[i + 1][j - 1]
            else:
                dp[i][j] = False
            if j - i + 1 >= k and dp[i][j]:
                count += 1
                i = j
                break
    return count

