    let currentSum = values[node];

    for (const child of tree.get(node)) {
        if (child !== parent) {
            currentSum ^= dfs(child, node, tree, values, ref);
        }
    }

    ref.firstMax = Math.max(ref.firstMax, currentSum);

    return currentSum;
}

