            freqMap[nums[right]]++;
            count++;
            right++;
        }

        max_score = std::max(max_score, (int)score);

        if (count == k) {
            score -= nums[left] * (freqMap[nums[left]] - 1);
            freqMap[nums[left]]--;
            count--;
        }
    }

    return max_score;
}

