import java.util.HashMap;
import java.util.ArrayList;

public int[][] shortestSubstringQueries(String s, int[][] queries){
    int n = s.length();
    HashMap<Integer, Integer> dp = new HashMap<>();

    for (int i = 0, val = 0, mask = 0; i < n; i++) {
        mask |= 1 << (s.charAt(i) - '0');
        val = (val << 1) | (s.charAt(i) - '0');

        for (int j = 0; j <= 9 && i + 1 - (1 << j) >= 0; j++) {
            int newVal = val & ((1 << (j + 1)) - 1);
            if (!dp.containsKey(newVal)) dp.put(newVal, i + 1 - (1 << j));
        }
    }

    int[][] ans = new int[queries.length][];
    for (int i = 0; i < queries.length; i++) {
        int target = queries[i][0] ^ queries[i][1];
        if (dp.containsKey(target))
            ans[i] = new int[] {dp.get(target), dp.get(target) + (int)(Math.log(target)/Math.log(2))};
        else
            ans[i] = new int[]{-1,-1};
    }
    return ans;
}

